// WF-11: SEO audit. Scaffold checks the known static-site pages against a
// checklist. Production: fetch each page and parse <title>, meta description,
// H1/H2, internal links, sitemap, robots, JSON-LD. High-impact fixes are
// REPORT-ONLY here — never auto-applied (approval-gated).
const pages = [
  { path: '/', title: 'Fortune U Group · Mutual Fund Distribution & Insurance · Tirupati' },
  { path: '/health.html', title: 'Health Insurance Calculator' },
  { path: '/services.html', title: 'Services' },
  { path: '/tools.html', title: 'SIP illustration' },
  { path: '/about.html', title: 'About Fortune U Group' },
  { path: '/contact.html', title: 'Contact Fortune U Group · Tirupati' },
  { path: '/disclosure.html', title: 'Regulatory disclosures · Fortune U Group' },
];

const checks = [];
for (const p of pages) {
  const t = p.title || '';
  checks.push({
    page: p.path,
    check: 'title_length',
    status: t.length >= 30 && t.length <= 60 ? 'PASS' : 'WARN',
    detail: 'title ' + t.length + ' chars',
  });
}
checks.push({
  page: '/', check: 'robots_txt', status: 'TODO',
  detail: 'Add robots.txt + sitemap.xml at repo root (currently only in legacy frontend/).',
});
checks.push({
  page: '/', check: 'json_ld', status: 'TODO',
  detail: 'Add FinancialService/InsuranceAgency JSON-LD to static pages.',
});

return checks.map((c) => ({ json: { ...c, audited_at: new Date().toISOString() } }));
